	"Define how many vacation days an employee is entitled to. Rules are evaluated top-down: a higher layer always wins. This page lets you see, edit, and simulate the full precedence chain." : "Definer, hvor mange feriedager en medarbeider har ret til. Regler evalueres top-down: et højere lag vinner alltid. Denne side lader deg se, redigere og simulere den fulde prioritetskæde.",
