	"Example for CSV\/JSON long layout: row 1 has date = first calendar day, start_time 22:00:00, end_time 23:59:59; row 2 has date = next day, start_time 00:00:00, end_time 06:00:00. Column working_hours is the work time share per segment (the segments sum to the full entry). This is not an extra \"break\" row — rest breaks remain tied to the original booking; split rows may show empty break columns." : "Eksempel på CSV\/JSON langt oppsett: rad 1 har dato = første kalenderdag, starttid 22:00:00, sluttid 23:59:59; rad 2 har dato = neste dag, starttid 00:00:00, sluttid 06:00:00. Kolonnen working_hours er arbeidstidsandelen per segment (segmentene summerer til hele registreringen). Dette er ikke en ekstra «pause»-rad – hvilepauser forblir knyttet til den opprinnelige registreringen; delte rader kan ha tomme pausekolonner.",
