	"For approved absences, an email with an iCal attachment (.ics) can be sent automatically." : "For godkjente fravær kan en e-mail med en iCal-knytt tilet fil (.ics) sendes automatisk.",
	"For clocked entries less than %d days old: use Edit to change times, or Delete to remove the entry entirely. Older clocked entries: use Request correction. Entries in a finalized month or approved by your manager cannot be deleted here." : "For stemplede registreringer yngre enn %d dager: bruk Rediger for å endre tider, eller Slett for å fjerne registreringen helt. Eldre stemplede registreringer: Be om korrigering. Registreringer i en avsluttet måned eller godkjent av lederen din kan ikke slettes her.",
	"For non-shift models (flex policy), automatic clock-out is suppressed inside this daytime window. Shift work remains strict." : "For ikke-skiftmodeller (fleksibel policy) undertrykkes automatisk utstempling i dette dagsvinduet. Skiftarbeid forblir strengt.",
	"For organization scope, download is available for working time export after preview." : "For organisasjonsomfang er nedlasting tilgjengelig for arbeidstidseksport etter forhåndsvisning.",
	"For payroll (DATEV) files, open Administration → Global settings and use the «Exports and reporting» section with your date range. This page offers CSV and JSON only." : "For lønningsfiler (DATEV) skal du åpne Administrasjon → Globale innstillinger og bruke seksjonen «Eksporter og rapportering» med ditt datointerval. Denne siden tilbyr kun CSV og JSON.",
	"For security and performance, entries load only when you click Show with a valid date range." : "Af sikkerheds- og performancehensyn lastes inn registreringer kun, når du klikker Vis med et gyldig datointerval.",
	"For security and performance, results are only loaded after both start and end date are set." : "Af sikkerheds- og performancehensyn lastes inn resultater først, når både start- og sluttdato er angivet.",
	"For the selected absence types, a substitute must be designated." : "For de valgte fraværstyper skal der udpeges en stedfortreder.",
	"Form actions" : "Form handlinger",
	"Form initialization failed. Please refresh the page." : "Skjemainitialisering mislyktes. Oppdater siden.",
	"Format: AZC2 followed by a signed payload. One key per organisation." : "Format: AZC2 efterfulgt av en signert nyttelast. Én nøkkel per organisasjon.",
	"Format: dd.mm.yyyy" : "Format: dd.mm.yyyy",
	"Formula: 30 × (work days per week ÷ 5)." : "Formel: 30 × (arbeidsdager om ugen ÷ 5).",
