	"German Labor Law (Arbeitszeitgesetz - ArbZG)" : "Tysk arbeidslov (Arbeitszeitgesetz - ArbZG)",
	"German labor law (ArbZG) allows a maximum of 10 hours per day. You have entered {hours} hours." : "Tysk arbeidsrett (ArbZG) tillater maksimalt 10 timer per dag. Du har angitt {hours} timer.",
	"German labor law (ArbZG) requires:" : "Tysk arbeidsrett (ArbZG) krever:",
	"German labor law compliance" : "Etterlevelse av tysk arbeidslovgivning",
	"German Labor Law Compliant" : "German Labor Law Compliant",
	"German labor law compliant time tracking for Nextcloud" : "Tidsregistrering i overensstemmelse med tysk arbeidslov for Nextcloud",
	"German labor law requires at least 30 minutes break after 6 hours of work. You have only {minutes} minutes." : "Tysk arbeidsrett krever minst 30 minutters pause etter 6 timers arbeid. Du har bare {minutes} minutter.",
	"German labor law requires at least 45 minutes break after 9 hours of work. You have only {minutes} minutes." : "Tysk arbeidsrett krever minst 45 minutters pause etter 9 timers arbeid. Du har bare {minutes} minutter.",
	"German law: 30 min break from 6 h work, 45 min from 9 h. Enable automatic breaks or add times yourself." : "Tysk lov: 30 min pause fra 6 timers arbeid, 45 min fra 9 timer. Aktiver automatiske pauser eller legg til tider selv.",
	"Gesamtzahl der Mitarbeitenden mit Zugriff auf die Zeiterfassung" : "Samlet antal medarbeidere med adgang til tidsregistrering",
	"Gesetzliche und zusätzliche Feiertage pro Bundesland verwalten. Diese Kalender werden für Urlaub, Arbeitszeitberechnung und Compliance-Prüfungen genutzt." : "Administrer lovpålagte og ytterligere helligdager per forbundsstat. Disse kalendere brukes til ferie, arbeidstidsberegning og etterlevelseskontroll.",
	"Get a notification when it's time to take a required break. For example, if you work more than 6 hours, you'll get a reminder to take at least a 30-minute break." : "Få en notifikation, når det er tid til at holde en påkrevd pause. Hvis du for eksempel jobber mer end 6 timer, får du en påmindelse om at holde mindst en 30-minutters pause.",
