	"How is this calculated?" : "How is this calculated?",
	"How it works" : "Hvordan det virker",
	"How Long to Keep Time Records" : "Hvor længe skal man opbevare tidsregistreringer",
	"How many hours of rest someone must have between the end of one work day and the start of the next. German law requires at least 11 hours. Example: If someone finishes work at 6 PM, they cannot start again before 5 AM the next day." : "Hvor mange timers hvile en person må ha mellom slutten av en arbeidsdag og starten av den neste. Tysk lov krever minst 11 timer. Eksempel: Hvis noen avslutter arbeidet kl. 18.00, kan de ikke starte igjen før kl. 05.00 neste dag.",
	"How many hours you normally work each day. Decimal values are allowed (e.g. 7.74 for a 38.7 h week spread over five days)." : "Hvor mange timer jobber du normalt hver dag. Decimalværdier er tillatt (f.eks. 7,74 for en uke på 38,7 timer fordelt på fem dager).",
	"How many vacation days you get each year. In Germany, the standard is 25 days. Example: Enter 25 if you get 25 vacation days per year." : "Hvor mange feriedager får du hvert år. I Tyskland er standarden 25 dager. Eksempel: Skriv inn 25, hvis du får 25 feriedager om året.",
	"How many years to keep time tracking records before they are automatically deleted. German law typically requires keeping records for 2 years. Example: Enter 2 to keep records for 2 years." : "Hvor mange år skal man opbevare tidsregistreringer, før de automatisk slettes. Tysk lov krever typisk journalføring i 2 år. Eksempel: Skriv inn 2 for at opbevare optegnelser i 2 år.",
