	"Identify this rule set" : "Identify this rule set",
	"If a break is left open for too long, the system automatically clocks out to prevent permanent pause status." : "Hvis en pause står åpen for lenge, avslutter systemet automatisk registreringen for å unngå permanent pausestatus.",
	"If a calendar month was finalized by mistake or a correction is required, you can reopen it here as an administrator for the employee whose month should be opened again. Use the search field to select that person (their Nextcloud account). You must enter a reason; the audit log records your administrator action, the reason, and who the change applies to. Previous snapshot rows remain in the database for traceability." : "Hvis en kalendermåned er avsluttet ved en feil, eller det er behov for en korrigering, kan du gjenåpne den her som administrator for medarbeideren hvis måned skal åpnes igjen. Bruk søkefeltet til å velge denne personen (Nextcloud-kontoen deres). Du må oppgi en begrunnelse; revisjonsloggen registrerer administratorhandlingen, begrunnelsen og hvem endringen gjelder. Tidligere snapshot-rader blir liggende i databasen for sporbarhet.",
	"If enabled, users can still turn this reminder off in their personal settings. Reminders are sent only for expected workdays (not weekends, holidays, or approved absences)." : "Hvis den er aktivert, kan brukere fortsatt slå denne påmindelse fra i deres personlige innstillinger. Påmindelser sendes kun for forventede arbeidsdager (ikke weekender, helligdager eller godkjent fravær).",
	"If enabled: managers are resolved from ArbeitszeitCheck teams defined below. If disabled: managers are resolved from shared Nextcloud groups (default behavior)." : "Hvis aktivert: ledere hentes fra ArbeitszeitCheck-team definert nedenfor. Hvis deaktivert: ledere hentes fra delte Nextcloud-grupper (standardatferd).",
	"If set, opening carryover per user cannot exceed this many days (Tarifvertrag \/ company policy). Leave empty for no cap. Imports and admin edits are clamped to this value." : "Hvis det er satt, kan åpneingsoverførsel per bruker ikke overstige så mange dager (Tarifvertrag \/ organisasjonspolicy). Lad være tom for ingen låg. Importer og administratorredigeringer er fastgjort til denne værdi.",
	"If set, this date is saved as the overtime “Stichtag” when the new account is created. Leave empty to configure later in ArbeitszeitCheck → Administration → Employees." : "Hvis angitt, lagres denne datoen som overtidens «Stichtag» når den nye kontoen opprettes. La stå tom for å konfigurere senere i ArbeitszeitCheck → Administrasjon → Ansatte.",
	"If you believe this is a mistake, contact your ArbeitszeitCheck administrator." : "Hvis du mener dette er en feil, kontakt ArbeitszeitCheck-administratoren din.",
	"If you manage more than one team, you can choose one here." : "Hvis du leder mer end ét team, kan du velge et her.",
	"If you need help at any time, check the documentation or contact your administrator." : "Hvis du til enhver tid har behov for hjælp, kan du sjekkke dokumentationen eller kontakte din administrator.",
	"If you need to generate reports, please contact your administrator or manager." : "Hvis du har behov for å generere rapporter, bedes du kontakte din administrator eller leder.",
	"If you think the result is wrong, please contact your HR administrator." : "Hvis du mener, at resultatet er forkert, bedes du kontakte din HR-administrator.",
	"If you were sick during vacation, please shorten or cancel the vacation first, then submit a separate sick leave request." : "Hvis du har været syg i ferien, bedes du først afkorte eller aflyse ferien og derefter sende inn en særskilt sykefraværsforespørsel.",
