	"Import file is too large (max 1 MB)" : "Import file is too large (max 1 MB)",
	"Important: This is best-effort email delivery, not a guaranteed real-time calendar sync. Delivery can be delayed or fail due to mail server\/network issues. Source of truth remains ArbeitszeitCheck." : "Vigtigt: Dette er den bedste e-mail-levering, ikke en garanteret kalendersynkronisering i realltid. Levering kan bli forsinket eller mislykkes på grund av problemer med mailserver\/netværk. Sandhedens kilde forblir ArbeitszeitCheck.",
	"In default mode, violations are shown but saving is still possible. In strict mode, violations prevent saving the time entry." : "I standardmodus vises overtredelser, men det er fortsatt mulig å lagre. I streng modus hindrer overtredelser lagring av tidsregistreringen.",
	"In the app guide: pick sign-in methods, set a secret admin PIN, and choose NFC or an external RFID reader." : "In the app guide: pick sign-in methods, set a secret admin PIN, and choose NFC or an external RFID reader.",
