	"Number of calendar days after the last day of each month for employees to finalize manually. If the month is still open after that, a daily job seals it automatically (same snapshot as manual finalize). Pending time entry or absence approvals block auto-finalization. Use 0 to disable automatic sealing." : "Antallll kalenderdagerr etter den siste dag i hver måned, som medarbeidere skal avlutte manuelt. Hvis måneden fortsatt er åben derefter, forsegler et dagligt job den automatisk (samme øjebliksbillede som manuell færdiggørelse). Ventende tidsregistrering eller fraværsgodkjennelse blokerer for automatisk avlutning. Bruk 0 for å deaktivere automatisk tætning.",
