	"Off" : "Off",
	"Off by default. Only enable if your collective agreement allows transferring unused annual leave; consult HR \/ legal. When on, unused annual days for the year may be added to the next year’s carryover opening, subject to the maximum carryover cap above." : "Fra som standard. Aktiver kun, hvis din overenskomst tillader overførsel av uudnyttet årlig ferie; konsultere HR \/ juridisk. Når den er aktivert, kan ubrugte årlige dager for året føjes til næste års fremførselsåpneing, med forbehold for det maksimale overførselsloft ovenfor.",
