	"On this page" : "On this page",
	"On {date}, the employee receives {days} vacation days per year, determined by the {layer}." : "Den {date} mottar medarbeideren {days} feriedager per år, bestemt av {layer}.",
	"Onboarding completed" : "Onboarding gjennomført",
