	"onboarding_completed" : "Onboarding gjennomført",
	"One row per segment (long)" : "En rad per segment (lang)",
	"One switch for your whole organisation. When it is on, every employee who uses ArbeitszeitCheck can optionally link their hours to a ProjectCheck project when they clock in or add a time entry. When it is off, no one sees a project picker and new links are blocked." : "Én bryter for hele organisasjonen. Når den er på, kan hver medarbeider som bruker ArbeitszeitCheck, valgfritt knytte timene sine til et ProjectCheck-prosjekt når de stempler inn eller legger til en tidsregistrering. Når den er av, ser ingen et prosjektvalg og nye koblinger blokkeres.",
	"One switch for your whole organisation. When it is on, every employee who uses ArbeitszeitCheck can optionally link their hours to a ProjectCheck project when they clock in or add a time entry. When it is off, no one sees a project picker and new links are blocked. The connection is off by default — turn it on here when you want to link working time to customer projects. Existing installs that already have linked time entries keep the connection on automatically after upgrade." : "Én bryter for hele organisasjonen. Når den er på, kan hver medarbeider som bruker ArbeitszeitCheck, valgfritt knytte timene sine til et ProjectCheck-prosjekt når de stempler inn eller legger til en tidsregistrering. Når den er av, ser ingen et prosjektvalg og nye koblinger blokkeres. Tilkoblingen er av som standard – slå den på her når du vil knytte arbeidstid til kundeprosjekter. Eksisterende installasjoner som allerede har koblede tidsregistreringer beholder tilkoblingen på automatisk etter oppgradering.",
