	"Only administrators can open this page while teams are off. Employees assigned as group managers cannot approve absences or corrections until you enable app teams and assign managers." : "Kun administratorer kan åpne denne side, mens team er slukket. Medarbeidere, det er tilknyttet som gruppeledere, kan ikke godkjenne fravær eller korreksjon, før du aktiverer appteam og tildeler ledere.",
