	"Optional region or labor jurisdiction this set applies to." : "Optional region or labor jurisdiction this set applies to.",
	"Optional. Leave empty if the rule set is open-ended." : "Optional. Leave empty if the rule set is open-ended.",
	"Optional: Add notes or details about this work period (e.g., project work, meetings, tasks)" : "Valgfritt: Legg til notater eller detaljer om denne arbeidsperioden (f.eks. prosjektarbeid, møter, oppgaver)",
	"Optional: filter by Nextcloud user ID. Maximum date range: %d days. Times use your personal timezone." : "Optional: filter by Nextcloud user ID. Maximum date range: %d days. Times use your personal timezone.",
	"Optional: Record your break times. Breaks of at least 15 minutes count toward legal requirements (ArbZG §4)." : "Valgfritt: Registrer pausetidene dine. Pauser på minst 15 minutter teller med i lovkrav (ArbZG §4).",
	"Optional: Record your break times. Breaks of at least 15 minutes count toward legal requirements (ArbZG §4). You can add multiple breaks." : "Valgfritt: Registrer pausetidene dine. Pauser på minst 15 minutter teller med i lovkrav (ArbZG §4). Du kan legge til flere pauser.",
	"Optional: Record your break times. German law requires breaks for work over 6 hours: 30 minutes for 6-9 hours, 45 minutes for 9+ hours. Shorter shifts have no break requirements. Automatic breaks are added when needed for compliance. You can add additional manual breaks." : "Valgfritt: Registrer pausetidene dine. Tysk lov krever pauser for arbeid over 6 timer: 30 minutter for 6–9 timer, 45 minutter for 9+ timer. Kortere skift har ingen pausekrav. Automatiske pauser legges til ved behov for etterlevelse. Du kan legge til flere manuelle pauser.",
	"Optional: set the overtime start date (Stichtag) and an opening balance for a calendar year." : "Optional: set the overtime start date (Stichtag) and an opening balance for a calendar year.",
	"Optional: When did your break end?" : "Valgfritt: Når sluttet pausen din?",
