	"Teams, Abteilungen oder andere Organisationseinheiten in einer flexiblen Hierarchie definieren. Mitglieder und Leitungen zuweisen. Wenn unten aktiviert, können Leitungen Abwesenheiten und Zeitkorrekturen ihrer Einheiten freigeben." : "Definer team, afdelinger eller andre organisatoriske enheter i et fleksibelt hierarki. Tildel medlemmer og kundeemner. Hvis det er aktivert nedenfor, kan linjer dele fravær og tidskorrektioner for deres enheter.",
