	"This time entry was changed by someone else. Please reload and try again." : "Denne tidsregistreringen ble endret av noen andre. Last inn på nytt og prøv igjen.",
	"This time entry would exceed the maximum daily working hours of 10 hours (ArbZG §3) on %1$s (%2$s hours on that calendar day)." : "This time entry would exceed the maximum daily working hours of 10 hours (ArbZG §3) on %1$s (%2$s hours on that calendar day).",
	"This time entry would exceed the maximum daily working hours of 10 hours (ArbZG §3). Total daily hours would be %s hours." : "Denne tidsregistrering ville overstige den maksimale daglige arbeidstid på 10 timer (ArbZG §3). Samlede daglige timer ville være %s timer.",
