	"Turn foyer tablet clocking on or off. Needs a Terminal license and at least one paired tablet." : "Turn foyer tablet clocking on or off. Needs a Terminal license and at least one paired tablet.",
	"Turn off manual entries if everyone must use the punch clock only." : "Slå manuelle registreringer fra, hvis alle kun skal bruke punch-uret.",
	"Turn off only if you want to enter every break manually." : "Sluk kun, hvis du vil skrive inn hver pause manuelt.",
	"Turn off stamping if your organisation records hours only via manual entries — the punch clock disappears for all employees." : "Slå stempling fra, hvis din organisasjon kun registrerer timer via manuelle registreringer - punch-uret forsvinner for alle medarbeidere.",
	"Turning this off hides the project picker everywhere and stops you from linking new hours to a project. Projects you already linked stay linked until a manager changes them. Projects with per-person pricing only appear if you are on the project team." : "Hvis du slår dette fra, skjules projektvelgeren overalt og forhindrer deg i at linke nye timene til et projekt. Prosjekter, du allerede har linket, forblir knyttet, til en leder endrer dem. Prosjekter med pris per person vises kun, hvis du er i projektteamet.",
