	"undecillionth" : "undecilionth",
	"Under GDPR, you have the right to access your personal data. You can export all your time tracking data at any time." : "I henhold til GDPR har du ret til at få adgang til dine personlige data. Du kan til enhver tid eksportere alle dine tidsregistreringsdata.",
	"Under the GDPR you can request a copy of your data, correction of inaccuracies or deletion of your records. ArbeitszeitCheck provides a self-service data export and deletion request inside the app under \"My settings\" → \"Data and privacy\"." : "Under the GDPR you can request a copy of your data, correction of inaccuracies or deletion of your records. ArbeitszeitCheck provides a self-service data export and deletion request inside the app under \"My settings\" → \"Data and privacy\".",
