	"Up to 1 employee may be re-resolved by this change." : "Op til 1 medarbeider kan bli genløst ved denne ændring.",
	"Up to two decimal places are allowed, e.g. 1.5 or 4.25 — comma or dot both work." : "Up to two decimal places are allowed, e.g. 1.5 or 4.25 — comma or dot both work.",
	"Up to {n} employees may be re-resolved by this change." : "Op til {n} medarbeidere kan bli genløst av denne ændring.",
	"Update" : "Oppdatering",
