	"Warning: 6-month average weekly working hours (%.2f h\/week) exceeds 48 hours\/week (ArbZG §3)." : "Advarsel: 6-måneders gjennomsnitlig ugentlig arbeidstid (%.2f t\/uke) overstiger 48 timer\/uke (ArbZG §3).",
	"Warning: 6-month average working hours (%.2f h\/day) exceeds 8 hours\/day. 10-hour days are only allowed if the average does not exceed 8 hours (ArbZG §3)." : "Advarsel: 6-måneders gjennomsnitlig arbeidstid (%.2f h\/dag) overstiger 8 timer\/dag. 10-timersdage er kun tillatt, hvis gjennomsnittet ikke overstiger 8 timer (ArbZG §3).",
	"Warning: employee list was truncated; contact support." : "Advarsel: medarbeiderlisten ble afkortet; kontakt support.",
