	"Year must be between 1900 and 2100. You entered %s." : "Årstal skal være mellem 1900 og 2100. Du indtastede %s.",
	"Year must be between 1900 and 2100. You entered {year}." : "År må være mellom 1900 og 2100. Du angav {year}.",
