	"Your recent time entries will appear here. Start by clocking in to track your working time." : "Dine seneste tidsregistreringer vises her. Start med at stemple ind for med å registrere din arbeidstid.",
	"Your recorded absences and their current status" : "Ditt registrerede fravær og deres nylige status",
	"Your selected substitute account was removed. Please edit this absence and choose a new substitute if required." : "Din valgte stedfortrederkonto ble fjernet. Rediger dette fravær og velg en ny stedfortreder, hvis det er nødvendigt.",
	"Your selection is saved automatically." : "Valget ditt lagres automatisk.",
	"Your session continues from yesterday. “Worked today” counts only the hours since midnight on the current calendar day (German labor law, ArbZG §3). The session timer shows your total working time since clock-in." : "Your session continues from yesterday. “Worked today” counts only the hours since midnight on the current calendar day (German labor law, ArbZG §3). The session timer shows your total working time since clock-in.",
	"Your session expired — please refresh the page and try again." : "Din session er utløpt — oppdater siden og prøv igjen.",
