	"Your working time is being recorded." : "Din arbeidstid blier registrert.",
	"Your working time model, vacation days, and working hours are assigned by your administrator. Contact your administrator if you have questions or need changes." : "Din arbeidstidsmodell, feriedager og arbeidstider tildeles av din administrator. Kontakt din administrator, hvis du har spørgsmål eller har behov for endringer.",
